import React, { useState, useRef, useEffect } from 'react';
import { Lock, Mail, ArrowRight, Eye, EyeOff, Activity, ShieldAlert, ChevronRight } from 'lucide-react';

const SignIn = () => {
  const [showPassword, setShowPassword] = useState(false);
  const [dragX, setDragX] = useState(0);
  const [isUnlocked, setIsUnlocked] = useState(false);
  const sliderRef = useRef(null);
  const isDragging = useRef(false);

  // Classic Slide Logic
  const handleStart = () => { isDragging.current = true; };
  const handleEnd = () => {
    isDragging.current = false;
    if (dragX > 200) {
      setDragX(280); // Snap to end
      setIsUnlocked(true);
      console.log("System Initialized");
    } else {
      setDragX(0); // Snap back
    }
  };

  const handleMove = (e) => {
    if (!isDragging.current || isUnlocked) return;
    const clientX = e.touches ? e.touches[0].clientX : e.clientX;
    const rect = sliderRef.current.getBoundingClientRect();
    let x = clientX - rect.left - 40; // Offset for handle size
    x = Math.max(0, Math.min(x, 280)); // Constrain to track width
    setDragX(x);
  };

  useEffect(() => {
    window.addEventListener('mousemove', handleMove);
    window.addEventListener('mouseup', handleEnd);
    window.addEventListener('touchmove', handleMove);
    window.addEventListener('touchend', handleEnd);
    return () => {
      window.removeEventListener('mousemove', handleMove);
      window.removeEventListener('mouseup', handleEnd);
      window.removeEventListener('touchmove', handleMove);
      window.removeEventListener('touchend', handleEnd);
    };
  }, [dragX]);

  return (
    <div className="flex flex-col items-center justify-center p-6 animate-slot">
      <div className="w-full max-w-[460px] flex flex-col">

        {/* HEADER */}
        <div className="bg-[#AB1717] border-[6px] border-[#47510B] rounded-t-[40px] p-8 red-stack-shadow relative z-20">
          <div className="flex items-center gap-5">
            <div className="bg-[#FDFAD8] p-3 rounded-xl border-4 border-[#47510B]">
              <ShieldAlert size={32} className="text-[#AB1717]" />
            </div>
            <h1 className="text-3xl font-black italic tracking-tighter text-[#FDFAD8] uppercase">
              TRASH<span className="text-[#CAD23C]">2</span>TRACK
            </h1>
          </div>
        </div>

        {/* BLENDED INPUT AREA */}
        <div className="bg-transparent border-x-[6px] border-[#47510B] p-10 flex flex-col gap-8 relative z-10">
          <div className="space-y-6">
            <input 
              type="email" 
              placeholder="IDENTITY" 
              className="w-full bg-white border-[5px] border-[#47510B] p-6 rounded-[20px] font-black text-xl outline-none shadow-[6px_6px_0_0_#47510B]"
            />
            <div className="relative">
              <input 
                type={showPassword ? "text" : "password"} 
                placeholder="PASSPHRASE" 
                className="w-full bg-white border-[5px] border-[#47510B] p-6 rounded-[20px] font-black text-xl outline-none shadow-[6px_6px_0_0_#47510B]"
              />
              <button onClick={() => setShowPassword(!showPassword)} className="absolute right-6 top-6 text-[#47510B] opacity-40">
                {showPassword ? <EyeOff size={22} /> : <Eye size={22} />}
              </button>
            </div>
          </div>
        </div>

        {/* CLASSIC SLIDE TO UNLOCK BUTTON (BEET RED TRACK) */}
        <div 
          ref={sliderRef}
          className="bg-[#AB1717] border-[6px] border-[#47510B] rounded-b-[40px] p-4 red-stack-shadow relative z-20 h-32 flex items-center overflow-hidden"
        >
          {/* Shimmering Text Label */}
          <div className={`absolute inset-0 flex items-center justify-center pointer-events-none transition-opacity duration-300 ${dragX > 50 ? 'opacity-0' : 'opacity-100'}`}>
            <span className="text-xl font-black uppercase tracking-[0.2em] animate-shimmer">
              Slide to Init
            </span>
          </div>

          {/* The Draggable Handle (Lemon Yellow) */}
          <div 
            onMouseDown={handleStart}
            onTouchStart={handleStart}
            style={{ transform: `translateX(${dragX}px)` }}
            className={`w-24 h-20 bg-[#CAD23C] border-4 border-[#47510B] rounded-[25px] flex items-center justify-center cursor-grab active:cursor-grabbing transition-shadow shadow-[4px_4px_0_0_#47510B] relative z-30 ${isUnlocked ? 'bg-[#47510B]' : ''}`}
          >
            {isUnlocked ? (
              <Activity className="text-[#CAD23C] animate-ping" />
            ) : (
              <div className="flex items-center">
                <ChevronRight className="text-[#47510B] -mr-3" size={32} strokeWidth={4} />
                <ChevronRight className="text-[#47510B]" size={32} strokeWidth={4} />
              </div>
            )}
          </div>

          {/* Success State Overlay */}
          {isUnlocked && (
            <div className="absolute inset-0 bg-[#CAD23C] flex items-center justify-center animate-pulse">
              <span className="text-[#47510B] font-black text-2xl italic uppercase tracking-tighter">ACCESS_GRANTED</span>
            </div>
          )}
        </div>

        <p className="text-center text-[10px] font-black uppercase tracking-[0.4em] text-[#AB1717] opacity-40 mt-6 italic">
          Hardware.Link.v3
        </p>
      </div>
    </div>
  );
};

export default SignIn;
